-- ١) الأولى: الرعايةُ أمانةٌ: الولدُ موهوبٌ لا مِلكٌ
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-riayah',
  'الأولى: الرعايةُ أمانةٌ: الولدُ موهوبٌ لا مِلكٌ',
  '«كُلُّكُمْ رَاعٍ فَمَسْئُولٌ عَنْ رَعِيَّتِهِ» مع آيتي التحريم والأنعام، وكلامِ ابن القيّم في إهمال التعليم.',
  '<h2>من القرآن الكريم</h2>
<p>{يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًۭا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌۭ شِدَادٌۭ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ} <strong>(سورة التحريم ٦٦، الآية ٦)</strong></p>
<p>{قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّۭا وَهُوَ رَبُّ كُلِّ شَىْءٍۢ ۚ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ} <strong>(سورة الأنعام ٦، الآية ١٦٤)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«كُلُّكُمْ رَاعٍ فَمَسْئُولٌ عَنْ رَعِيَّتِهِ، فَالأَمِيرُ الَّذِي عَلَى النَّاسِ رَاعٍ وَهْوَ مَسْئُولٌ عَنْهُمْ، وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ وَهْوَ مَسْئُولٌ عَنْهُمْ، وَالْمَرْأَةُ رَاعِيَةٌ عَلَى بَيْتِ بَعْلِهَا وَوَلَدِهِ وَهْىَ مَسْئُولَةٌ عَنْهُمْ، وَالْعَبْدُ رَاعٍ عَلَى مَالِ سَيِّدِهِ وَهْوَ مَسْئُولٌ عَنْهُ، أَلاَ فَكُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ» — <strong>صحيح البخاري</strong>، برقم ٢٥٥٤.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«فمن أهمل تعليم ولده ما ينفعه وتركه سدى فقد أساء إليه غاية الإساءة وأكثر الأولاد إنما جاء فسادهم من قبل الآباء وإهمالهم لهم وترك تعليمهم فرائض الدين وسننه فأضاعوهم صغارا فلم ينتفعوا بأنفسهم ولم ينفعوا آباءهم كبارا»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب الخامس عشر في وجوب تأديب الأولاد وتعليمهم والعدل بينهم.</blockquote>
<blockquote>«من ولد له ولد فليحسن اسمه وأدبه فإذا بلغ فليزوجه فإن بلغ ولم يزوجه فأصاب إثما فإنما إثمه على أبيه»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب الخامس عشر — حقوق الولد على أبيه.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>ابدأ بنفسك: السؤالُ يومَ القيامةِ على ما وليتَ لا على ما بلغَ.</li><li>اجعلَ للتعهدِ وقتًا ثابتًا في اليوم، ولو قصيرًا، فالحسابُ على الضياع لا على القلة.</li><li>لا تقل «سيعلِمُه الزمن»: الزمنُ يعلّمُ ما تُرسلُه إليه أنت.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: التحريم ٦٦/٦؛ الأنعام ٦/١٦٤ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح البخاري ٢٥٥٤ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  'تحفة المودود بأحكام المولود — ابن القيّم (ت ٧٥١هـ)',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  '["الرعاية أمانة","تربية الأبناء","ابن القيّم"]'::jsonb,
  '{"البطاقة":"١ من ١٥","من القرآن":"التحريم ٦٦/٦؛ الأنعام ٦/١٦٤","من الحديث":"صحيح البخاري ٢٥٥٤","من الكتب":"تحفة المودود بأحكام المولود","الرخصة":"ويكي مصدر — CC BY-SA 4.0؛ AlQuran Cloud (Tanzil)؛ hadith-api — Unlicense"}'::jsonb,
  'published', 150,
  '2026-10-22T00:00:00.000Z'::timestamptz
where not exists (select 1 from public.items where section_id = 'tarbiyah' and slug = 'tarbiyah-riayah');

-- ٢) الثانية: الرحمةُ بالولدِ: حضنٌ وتقبيلٌ لا ضعفٌ
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-rahmah',
  'الثانية: الرحمةُ بالولدِ: حضنٌ وتقبيلٌ لا ضعفٌ',
  'تقبيلُ النبيِّ ﷺ الحسنَ، و«أرحمُكم بالعيال»، ولفظُ ابن القيّم في الرحمة بالأطفال وإسكان الفزع.',
  '<h2>من القرآن الكريم</h2>
<p>{فَبِمَا رَحْمَةٍۢ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ} <strong>(سورة آل عمران ٣، الآية ١٥٩)</strong></p>
<p>{وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةًۭ لِّلْعَٰلَمِينَ} <strong>(سورة الأنبياء ٢١، الآية ١٠٧)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«قَبَّلَ رَسُولُ اللَّهِ صلى الله عليه وسلم الْحَسَنَ بْنَ عَلِيٍّ وَعِنْدَهُ الأَقْرَعُ بْنُ حَابِسٍ التَّمِيمِيُّ جَالِسًا. فَقَالَ الأَقْرَعُ إِنَّ لِي عَشَرَةً مِنَ الْوَلَدِ مَا قَبَّلْتُ مِنْهُمْ أَحَدًا. فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ مَنْ لاَ يَرْحَمُ لاَ يُرْحَمُ» — <strong>صحيح البخاري</strong>، برقم ٥٩٩٧، كتاب الأدب.</p>
<p>«قَدِمَ نَاسٌ مِنَ الأَعْرَابِ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالُوا أَتُقَبِّلُونَ صِبْيَانَكُمْ فَقَالُوا نَعَمْ. فَقَالُوا لَكِنَّا وَاللَّهِ مَا نُقَبِّلُ. فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَمْلِكُ إِنْ كَانَ اللَّهُ نَزَعَ مِنْكُمُ الرَّحْمَةَ. وَقَالَ ابْنُ نُمَيْرٍ مِنْ قَلْبِكَ الرَّحْمَةَ» — <strong>صحيح مسلم</strong>، برقم ٦٠٢٧، كتاب الفضائل.</p>
<p>«مَا رَأَيْتُ أَحَدًا كَانَ أَرْحَمَ بِالْعِيَالِ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم - قَالَ - كَانَ إِبْرَاهِيمُ مُسْتَرْضِعًا لَهُ فِي عَوَالِي الْمَدِينَةِ فَكَانَ يَنْطَلِقُ وَنَحْنُ مَعَهُ فَيَدْخُلُ الْبَيْتَ وَإِنَّهُ لَيُدَّخَنُ وَكَانَ ظِئْرُهُ قَيْنًا فَيَأْخُذُهُ فَيُقَبِّلُهُ ثُمَّ يَرْجِعُ. قَالَ عَمْرٌو فَلَمَّا تُوُفِّيَ إِبْرَاهِيمُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِنَّ إِبْرَاهِيمَ ابْنِي وَإِنَّهُ مَاتَ فِي الثَّدْىِ وَإِنَّ لَهُ لَظِئْرَيْنِ تُكَمِّلاَنِ رَضَاعَهُ فِي الْجَنَّةِ» — <strong>صحيح مسلم</strong>، برقم ٦٠٢٦، كتاب الفضائل.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«وفيه الرحمة بالأطفال وفيه تعليم التواضع ومكارم الأخلاق»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب الثالث عشر في جواز حمل الأطفال في الصلاة.</blockquote>
<blockquote>«فإن في إهماله إسكان الفزع والروع في قلبه فينشأ على ذلك»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب السادس عشر — فصول في تربية الأطفال.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>أظهر الرحمةَ أمامه: القُبلةُ والحضنُ تعليمٌ قبل أن يكونا حنانًا.</li><li>لا تُسكِت البكاءَ بالتخويف؛ أسكِتْهُ بالأمان، ثم علّمه الكلامَ بدل الصراخ.</li><li>من اتُّهم باللين فليذكر: «مَنْ لا يَرْحَمُ لا يُرْحَمُ».</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
