-- ٣) الثالثة: الرفقُ والتدرّجُ: يُلقى إليه الجلى اللائقُ به
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-rifq',
  'الثالثة: الرفقُ والتدرّجُ: يُلقى إليه الجلى اللائقُ به',
  '«يَسِّرُوا وَلاَ تُعَسِّرُوا» و«الرفق» في مسلم، مع وظيفةِ الغزالي السابعة في مراعاةِ عقلِ المتعلم.',
  '<h2>من القرآن الكريم</h2>
<p>{ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ} <strong>(سورة النحل ١٦، الآية ١٢٥)</strong></p>
<p>{فَقُولَا لَهُۥ قَوْلًۭا لَّيِّنًۭا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ} <strong>(سورة طه ٢٠، الآية ٤٤)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«يَسِّرُوا وَلاَ تُعَسِّرُوا، وَبَشِّرُوا وَلاَ تُنَفِّرُوا» — <strong>صحيح البخاري</strong>، برقم ٦٩، كتاب العلم.</p>
<p>«إِنَّ الرِّفْقَ لاَ يَكُونُ فِي شَىْءٍ إِلاَّ زَانَهُ وَلاَ يُنْزَعُ مِنْ شَىْءٍ إِلاَّ شَانَهُ» — <strong>صحيح مسلم</strong>، برقم ٦٦٠٢، كتاب البر والصلة والأدب.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«الوظيفة السابعة أن المتعلم القاصر ينبغي أن يلقى إليه الجلى اللائق به ولا يذكر له وراء هذا تدقيقاً وهو يدخره عنه فإن ذلك يفتر رغبته في الجلى ويشوش عليه قلبه ويوهم إليه البخل به عنه إذ يظن كل أحد أنه أهل لكل علم دقيق»<br>— أبو حامد الغزالي (ت ٥٠٥هـ)، <a href="https://ar.wikisource.org/wiki/%D8%A5%D8%AD%D9%8A%D8%A7%D8%A1_%D8%B9%D9%84%D9%88%D9%85_%D8%A7%D9%84%D8%AF%D9%8A%D9%86/%D9%83%D8%AA%D8%A7%D8%A8_%D8%A7%D9%84%D8%B9%D9%84%D9%85/%D8%A7%D9%84%D8%A8%D8%A7%D8%A8_%D8%A7%D9%84%D8%AE%D8%A7%D9%85%D8%B3">إحياء علوم الدين — كتاب العلم، الباب الخامس</a>: الوظيفة السابعة للمعلم.</blockquote>
<blockquote>«كل لكل عبد بمعيار عقله وزن له بميزان فهمه حتى تسلم منه وينتفع بك وإلا وقع الإنكار لتفاوت المعيار»<br>— أبو حامد الغزالي (ت ٥٠٥هـ)، <a href="https://ar.wikisource.org/wiki/%D8%A5%D8%AD%D9%8A%D8%A7%D8%A1_%D8%B9%D9%84%D9%88%D9%85_%D8%A7%D9%84%D8%AF%D9%8A%D9%86/%D9%83%D8%AA%D8%A7%D8%A8_%D8%A7%D9%84%D8%B9%D9%84%D9%85/%D8%A7%D9%84%D8%A8%D8%A7%D8%A8_%D8%A7%D9%84%D8%AE%D8%A7%D9%85%D8%B3">إحياء علوم الدين — كتاب العلم، الباب الخامس</a>: فصل في مخاطبة المتعلم على قدر عقله.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>قِسْ ما تُلقنه بعقله اليوم، لا بطموحك أنت.</li><li>خطوةٌ واحدةٌ تُتمُّها خيرٌ من عشرةٍ تُعقِّدُها عليه.</li><li>إذا أعياك الأمرُ فغيّر الطريقةَ قبل أن تغيّر العقوبة.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: النحل ١٦/١٢٥؛ طه ٢٠/٤٤ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح البخاري ٦٩؛ صحيح مسلم ٦٦٠٢ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: إحياء علوم الدين — كتاب العلم، الباب الخامس — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D8%A5%D8%AD%D9%8A%D8%A7%D8%A1_%D8%B9%D9%84%D9%88%D9%85_%D8%A7%D9%84%D8%AF%D9%8A%D9%86/%D9%83%D8%AA%D8%A7%D8%A8_%D8%A7%D9%84%D8%B9%D9%84%D9%85/%D8%A7%D9%84%D8%A8%D8%A7%D8%A8_%D8%A7%D9%84%D8%AE%D8%A7%D9%85%D8%B3',
  'إحياء علوم الدين — كتاب العلم، الباب الخامس — أبو حامد الغزالي (ت ٥٠٥هـ)',
  'https://ar.wikisource.org/wiki/%D8%A5%D8%AD%D9%8A%D8%A7%D8%A1_%D8%B9%D9%84%D9%88%D9%85_%D8%A7%D9%84%D8%AF%D9%8A%D9%86/%D9%83%D8%AA%D8%A7%D8%A8_%D8%A7%D9%84%D8%B9%D9%84%D9%85/%D8%A7%D9%84%D8%A8%D8%A7%D8%A8_%D8%A7%D9%84%D8%AE%D8%A7%D9%85%D8%B3',
