-- ٤) الرابعة: العدلُ بين الأبناء: في العطاءِ وفي القبلة
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-adl',
  'الرابعة: العدلُ بين الأبناء: في العطاءِ وفي القبلة',
  'حديثُ النعمان بن بشير في البخاري ومسلم، وقصةُ «فما عدلت بينهما»، مع كلامِ ابن القيّم في وجوب العدل.',
  '<h2>من القرآن الكريم</h2>
<p>{۞ إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ} <strong>(سورة النحل ١٦، الآية ٩٠)</strong></p>
<p>{۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ ۚ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًۭا فَٱللَّهُ أَوْلَىٰ بِهِمَا ۖ فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ ۚ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا} <strong>(سورة النساء ٤، الآية ١٣٥)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«أَعْطَانِي أَبِي عَطِيَّةً، فَقَالَتْ عَمْرَةُ بِنْتُ رَوَاحَةَ لاَ أَرْضَى حَتَّى تُشْهِدَ رَسُولَ اللَّهِ صلى الله عليه وسلم. فَأَتَى رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ إِنِّي أَعْطَيْتُ ابْنِي مِنْ عَمْرَةَ بِنْتِ رَوَاحَةَ عَطِيَّةً، فَأَمَرَتْنِي أَنْ أُشْهِدَكَ يَا رَسُولَ اللَّهِ. قَالَ أَعْطَيْتَ سَائِرَ وَلَدِكَ مِثْلَ هَذَا. قَالَ لاَ. قَالَ فَاتَّقُوا اللَّهَ، وَاعْدِلُوا بَيْنَ أَوْلاَدِكُمْ. قَالَ فَرَجَعَ فَرَدَّ عَطِيَّتَهُ» — <strong>صحيح البخاري</strong>، برقم ٢٥٨٧.</p>
<p>«تَصَدَّقَ عَلَىَّ أَبِي بِبَعْضِ مَالِهِ فَقَالَتْ أُمِّي عَمْرَةُ بِنْتُ رَوَاحَةَ لاَ أَرْضَى حَتَّى تُشْهِدَ رَسُولَ اللَّهِ صلى الله عليه وسلم. فَانْطَلَقَ أَبِي إِلَى النَّبِيِّ صلى الله عليه وسلم لِيُشْهِدَهُ عَلَى صَدَقَتِي فَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم أَفَعَلْتَ هَذَا بِوَلَدِكَ كُلِّهِمْ. قَالَ لاَ. قَالَ اتَّقُوا اللَّهَ وَاعْدِلُوا فِي أَوْلاَدِكُمْ. فَرَجَعَ أَبِي فَرَدَّ تِلْكَ الصَّدَقَةَ» — <strong>صحيح مسلم</strong>، برقم ٤١٨١، كتاب الهبات.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«ومن حقوق الأولاد العدل بينهم في العطاء والمنع ففي السنن ومسند أحمد وصحيح ابن حبان من حديث النعمان بن بشير قال قال رسول الله اعدلوا بين أبنائكم اعدلوا بين أبنائكم»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: فصل: من حقوق الأولاد العدل بينهم في العطاء والمنع.</blockquote>
<blockquote>«أن رجلا كان جالسا مع النبي فجاء بني له فقبله وأجلسه في حجره ثم جاءت بنية فأخذها فأجلسها إلى جنبه فقال النبي فما عدلت بينهما وكان السلف يستحبون أن يعدلوا بين الأولاد في القبلة»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب الخامس عشر — عدلُ القبلة.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>اعدل في النظرةِ والقُبلةِ كما تعدل في النقطة؛ فالطفلُ لا يُخطئ المكيال.</li><li>العدلُ ليس تشابهَ العطاءِ دائمًا، بل عدمَ المحاباةِ فيما يُشعَر.</li><li>إذا ميّزتَ أحدًا لسببٍ (مرضٍ، عذرٍ) فبيّن السبب، فالفهمُ أبقى من الحقد.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: النحل ١٦/٩٠؛ النساء ٤/١٣٥ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح البخاري ٢٥٨٧؛ صحيح مسلم ٤١٨١ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  'تحفة المودود بأحكام المولود — ابن القيّم (ت ٧٥١هـ)',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  '["العدل بين الأبناء","تربية الأبناء","ابن القيّم"]'::jsonb,
  '{"البطاقة":"٤ من ١٥","من القرآن":"النحل ١٦/٩٠؛ النساء ٤/١٣٥","من الحديث":"صحيح البخاري ٢٥٨٧؛ صحيح مسلم ٤١٨١","من الكتب":"تحفة المودود بأحكام المولود","الرخصة":"ويكي مصدر — CC BY-SA 4.0؛ AlQuran Cloud (Tanzil)؛ hadith-api — Unlicense"}'::jsonb,
