-- ٦) السادسة: الصلاةُ والقرآنُ: أولُ ما يُبتدأُ به
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-salat-quran',
  'السادسة: الصلاةُ والقرآنُ: أولُ ما يُبتدأُ به',
  '«خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ» وأمرُ «مروا أبناءكم بالصلاة لسبع» كما يورده ابن القيّم من سنن أبي داود.',
  '<h2>من القرآن الكريم</h2>
<p>{يَٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ وَٱصْبِرْ عَلَىٰ مَآ أَصَابَكَ ۖ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ} <strong>(سورة لقمان ٣١، الآية ١٧)</strong></p>
<p>{هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّۦنَ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍۢ} <strong>(سورة الجمعة ٦٢، الآية ٢)</strong></p>
<p>{فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۗ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ ۖ وَقُل رَّبِّ زِدْنِى عِلْمًۭا} <strong>(سورة طه ٢٠، الآية ١١٤)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَه» — <strong>صحيح البخاري</strong>، برقم ٥٠٢٧.</p>
<p>«مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ، وَإِنَّمَا أَنَا قَاسِمٌ وَاللَّهُ يُعْطِي، وَلَنْ تَزَالَ هَذِهِ الأُمَّةُ قَائِمَةً عَلَى أَمْرِ اللَّهِ لاَ يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ» — <strong>صحيح البخاري</strong>، برقم ٧١، كتاب العلم.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«مروا أبناءكم بالصلاة لسبع واضربوهم عليها لعشر وفرقوا بينهم في المضاجع ففي هذا الحديث ثلاثة آداب أمرهم بها وضربهم عليها والتفريق بينهم في المضاجع»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب الخامس عشر — حديث عمرو بن شعيب (في سنن أبي داود).</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>السنُّ التي يُبدأُ فيها الصلاةُ سبعٌ: تعويدٌ بالتدرج لا تكليفٌ قبل الطاقَة.</li><li>ليكن لك وِردٌ يُرى في البيت: الطفلُ يتعلمُ من منظركَ أكثرَ من مسمعك.</li><li>حفظُ القليلِ بدوامٍ أنفعُ من كثيرٍ لا يُثبَّت.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: لقمان ٣١/١٧؛ الجمعة ٦٢/٢؛ طه ٢٠/١١٤ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح البخاري ٥٠٢٧؛ صحيح البخاري ٧١ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
