  '["الصلاة والقرآن","تربية الأبناء","ابن القيّم"]'::jsonb,
  '{"البطاقة":"٦ من ١٥","من القرآن":"لقمان ٣١/١٧؛ الجمعة ٦٢/٢؛ طه ٢٠/١١٤","من الحديث":"صحيح البخاري ٥٠٢٧؛ صحيح البخاري ٧١","من الكتب":"تحفة المودود بأحكام المولود","الرخصة":"ويكي مصدر — CC BY-SA 4.0؛ AlQuran Cloud (Tanzil)؛ hadith-api — Unlicense"}'::jsonb,
  'published', 100,
  '2026-10-22T00:00:00.000Z'::timestamptz
