-- ٧) السابعة: القدوةُ قبل الوعظ: عظْ نفسَك أولًا
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-qudwa',
  'السابعة: القدوةُ قبل الوعظ: عظْ نفسَك أولًا',
  '«كَانَ فِي مِهْنَةِ أَهْلِهِ»، و«أتأمرون الناس بالبر…» مع قصمِ ظهرِ عليٍّ، ووصيةِ الغزالي «عظ نفسك».',
  '<h2>من القرآن الكريم</h2>
<p>{يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ} <strong>(سورة الصف ٦١، الآية ٢)</strong></p>
<p>{۞ أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ ۚ أَفَلَا تَعْقِلُونَ} <strong>(سورة البقرة ٢، الآية ٤٤)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«كَانَ يَكُونُ فِي مِهْنَةِ أَهْلِهِ ـ تَعْنِي خِدْمَةَ أَهْلِهِ ـ فَإِذَا حَضَرَتِ الصَّلاَةُ خَرَجَ إِلَى الصَّلاَةِ» — <strong>صحيح البخاري</strong>، برقم ٦٧٦.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«أتأمرون الناس بالبر وتنسون أنفسكم ولذلك كان وزر العالم في معاصيه أكثر من وزر الجاهل إذ يزل بزلته علام كثير ويقتدون به. ومن سن سنة سيئة فعليه وزرها ووزر من عمل بها. ولذلك قال علي رضي الله عنه قصم ظهري رجلان؛ عالم متهتك وجاهل متنسك؛ فالجاهل يغر الناس بتنسكه، والعالم يغرهم بتهتكه»<br>— أبو حامد الغزالي (ت ٥٠٥هـ)، <a href="https://ar.wikisource.org/wiki/%D8%A5%D8%AD%D9%8A%D8%A7%D8%A1_%D8%B9%D9%84%D9%88%D9%85_%D8%A7%D9%84%D8%AF%D9%8A%D9%86/%D9%83%D8%AA%D8%A7%D8%A8_%D8%A7%D9%84%D8%B9%D9%84%D9%85/%D8%A7%D9%84%D8%A8%D8%A7%D8%A8_%D8%A7%D9%84%D8%AE%D8%A7%D9%85%D8%B3">إحياء علوم الدين — كتاب العلم، الباب الخامس</a>: فصل في مخالفة العالم بعلمه.</blockquote>
<blockquote>«يا ابن مريم عظ نفسك، فان اتعظت فعظ الناس، وإلا فاستح من الله»<br>— أبو حامد الغزالي (ت ٥٠٥هـ)، <a href="https://ar.wikisource.org/wiki/%D8%A3%D9%8A%D9%87%D8%A7_%D8%A7%D9%84%D9%88%D9%84%D8%AF">أيها الولد</a>: وصية الغزالي في العمل قبل التعليم.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>ما فعلتَه أمامه أثبتُ مما أوجبتَه عليه.</li><li>لا تطالبْ بما لا تحتمل؛ الوعظُ المخالفُ للفعل يُسقطُ الهيبةَ لا الذنبَ فقط.</li><li>إذا أمرتَ بأمرٍ فابدأ بنفسك في الساعة نفسها.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: الصف ٦١/٢؛ البقرة ٢/٤٤ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح البخاري ٦٧٦ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: إحياء علوم الدين — كتاب العلم، الباب الخامس؛ أيها الولد — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D8%A5%D8%AD%D9%8A%D8%A7%D8%A1_%D8%B9%D9%84%D9%88%D9%85_%D8%A7%D9%84%D8%AF%D9%8A%D9%86/%D9%83%D8%AA%D8%A7%D8%A8_%D8%A7%D9%84%D8%B9%D9%84%D9%85/%D8%A7%D9%84%D8%A8%D8%A7%D8%A8_%D8%A7%D9%84%D8%AE%D8%A7%D9%85%D8%B3',
  'إحياء علوم الدين — كتاب العلم، الباب الخامس — أبو حامد الغزالي (ت ٥٠٥هـ)',
  'https://ar.wikisource.org/wiki/%D8%A5%D8%AD%D9%8A%D8%A7%D8%A1_%D8%B9%D9%84%D9%88%D9%85_%D8%A7%D9%84%D8%AF%D9%8A%D9%86/%D9%83%D8%AA%D8%A7%D8%A8_%D8%A7%D9%84%D8%B9%D9%84%D9%85/%D8%A7%D9%84%D8%A8%D8%A7%D8%A8_%D8%A7%D9%84%D8%AE%D8%A7%D9%85%D8%B3',
  '["القدوة قبل الوعظ","تربية الأبناء","أبو حامد الغزالي"]'::jsonb,
  '{"البطاقة":"٧ من ١٥","من القرآن":"الصف ٦١/٢؛ البقرة ٢/٤٤","من الحديث":"صحيح البخاري ٦٧٦","من الكتب":"إحياء علوم الدين — كتاب العلم، الباب الخامس؛ أيها الولد","الرخصة":"ويكي مصدر — CC BY-SA 4.0؛ AlQuran Cloud (Tanzil)؛ hadith-api — Unlicense"}'::jsonb,
  'published', 90,
  '2026-10-22T00:00:00.000Z'::timestamptz
