   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-ghadab',
  'الثامنة: غضبُ الوالدِ: الشديدةُ التي تملكُ نفسَها',
  '«لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ» في البخاري ومسلم، وتحذيرُ ابن القيّم أن ينشأ الولدُ على الحردِ واللجاج.',
  '<h2>من القرآن الكريم</h2>
<p>{وَٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ} <strong>(سورة الشورى ٤٢، الآية ٣٧)</strong></p>
<p>{وَعِبَادُ ٱلرَّحْمَٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًۭا وَإِذَا خَاطَبَهُمُ ٱلْجَٰهِلُونَ قَالُوا۟ سَلَٰمًۭا} <strong>(سورة الفرقان ٢٥، الآية ٦٣)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ» — <strong>صحيح البخاري</strong>، برقم ٦١١٤، كتاب الأدب.</p>
<p>«لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ» — <strong>صحيح مسلم</strong>، برقم ٦٦٤٣، كتاب البر والصلة والأدب.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«فإنه ينشأ على ما عوده المربي في صغره من حرد وغضب ولجاج وعجلة وخفة مع هواه وطيش وحدة وجشع فيصعب عليه في كبره تلافي ذلك وتصير هذه الأخلاق صفات وهيئات راسخة له فلو تحرز منها غاية التحرز فضحته ولا بد يوما ما ولهذا تجد أكثر الناس منحرفة أخلاقهم وذلك من قبل التربية التي نشأ عليها»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب السادس عشر — الاعتناء بأمر الخُلق.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>لا قرارَ تأديبيَّ وأنتَ غضبان: أجّلْ حتى تسلم من نفسك.</li><li>أعلنْ سبب الغضبِ لا حجمَه: «أغضبني كذبُك» لا «أنا سأنالك».</li><li>إن تجاوزتَ فاستغفرْ أمامه؛ فالرجوعُ عن الخطأ مدرسةٌ في النبل.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: الشورى ٤٢/٣٧؛ الفرقان ٢٥/٦٣ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح البخاري ٦١١٤؛ صحيح مسلم ٦٦٤٣ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
