-- ٩) التاسعة: الخُلُقُ يُكتسَبُ بالتعويدِ لا بالتشديد
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-khuluq',
  'التاسعة: الخُلُقُ يُكتسَبُ بالتعويدِ لا بالتشديد',
  '«إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ» في مسلم، مع تحذيرِ ابن القيّم من الكذبِ ومجالسِ اللهوِ وتعويدِ البذل.',
  '<h2>من القرآن الكريم</h2>
<p>{يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّٰدِقِينَ} <strong>(سورة التوبة ٩، الآية ١١٩)</strong></p>
<p>{يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًۭا سَدِيدًۭا} <strong>(سورة الأحزاب ٣٣، الآية ٧٠)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ صِدِّيقًا وَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ وَإِنَّ الرَّجُلَ لَيَكْذِبُ حَتَّى يُكْتَبَ كَذَّابًا» — <strong>صحيح مسلم</strong>، برقم ٦٦٣٧، كتاب البر والصلة والأدب.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«وينبغي لوليه أن يجنبه الأخذ من غيره غاية التجنب فإنه متى اعتاد الأخذ صار له طبيعة ونشأ بأن يأخذ لا بأن يعطي ويعوده البذل والإعطاء وإذا أراد الولي أن يعطي شيئا أعطاه إياه على يده ليذوق حلاوة الإعطاء ويجنبه الكذب والخيانة أعظم مما يجنبه السم الناقع فإنه متى سهل له سبيل الكذب والخيانة أفسد عليه سعادة الدنيا والآخرة وحرمه كل خير»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب السادس عشر — تجنّب الكذب والخيانة.</blockquote>
<blockquote>«وكذلك يجب أن يتجنب الصبي إذا عقل مجالس اللهو والباطل والغناء وسماع الفحش والبدع ومنطق السوء فإنه إذا علق بسمعه عسر عليه مفارقته في الكبر وعز على وليه استنقاذه منه»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب السادس عشر — مجالس اللهو والباطل.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>جرّبْه على الصدقِ في يسيرِ المالِ، فالكذبُ يبدأُ من الحسابِ الصغير.</li><li>لا تكافئ الصدقَ العقابيَّ بالعقوبة؛ وإلا تعلَّم الصمتَ لا الأمانة.</li><li>أعِدِ الباذلَ على يديه حتى «يذوقَ حلاوةَ الإعطاء» كما قال ابن القيّم.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: التوبة ٩/١١٩؛ الأحزاب ٣٣/٧٠ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح مسلم ٦٦٣٧ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
