-- ١٠) العاشرة: البنتُ بُشرى لا خسارة
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-banat',
  'العاشرة: البنتُ بُشرى لا خسارة',
  '«مَنْ عَالَ جَارِيَتَيْنِ…» و«مَنْ يَلِي مِنْ هَذِهِ الْبَنَاتِ شَيْئًا…»، مع ردِّ ابن القيّم على تسخط الإناث.',
  '<h2>من القرآن الكريم</h2>
<p>{وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّۭا وَهُوَ كَظِيمٌۭ} <strong>(سورة النحل ١٦، الآية ٥٨)</strong></p>
<p>{لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ يَخْلُقُ مَا يَشَآءُ ۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثًۭا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ} <strong>(سورة الشورى ٤٢، الآية ٤٩)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«مَنْ عَالَ جَارِيَتَيْنِ حَتَّى تَبْلُغَا جَاءَ يَوْمَ الْقِيَامَةِ أَنَا وَهُوَ. وَضَمَّ أَصَابِعَهُ» — <strong>صحيح مسلم</strong>، برقم ٦٦٩٥، كتاب البر والصلة والأدب.</p>
<p>«مَنْ يَلِي مِنْ هَذِهِ الْبَنَاتِ شَيْئًا فَأَحْسَنَ إِلَيْهِنَّ كُنَّ لَهُ سِتْرًا مِنَ النَّارِ» — <strong>صحيح البخاري</strong>، برقم ٥٩٩٥، كتاب الأدب.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«والمقصود أن التسخط بالإناث من أخلاق الجاهلية الذين ذمهم الله تعالى في قوله وإذا بشر أحدهم بالأنثى ظل وجهه مسودا وهو كظيم يتوارى من القوم من سوء ما بشر به أيمسكه على هون أم يدسه في التراب ألا ساء ما يحكمون»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب الثاني في كراهة تسخط البنات.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>لا تُشعِرْها أنها «أخفُّ» في البيت ولا في الميراثِ المقسومِ لها رضاءً.</li><li>العلمُ والعملُ لها كبنيها؛ فالنصفُ الضائعُ نصفُ المجتمع.</li><li>احفظْ لها حقَّها في البرِّ من أخيها كما حفظتَ حقَّه في الرفق.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: النحل ١٦/٥٨؛ الشورى ٤٢/٤٩ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح مسلم ٦٦٩٥؛ صحيح البخاري ٥٩٩٥ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  'تحفة المودود بأحكام المولود — ابن القيّم (ت ٧٥١هـ)',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  '["البنت بشرى لا خسارة","تربية الأبناء","ابن القيّم"]'::jsonb,
