-- ١١) الحادية عشرة: الاسمُ والفطرةُ: أولُ ما يُقرعُ المسامعَ
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-isma-fitra',
  'الحادية عشرة: الاسمُ والفطرةُ: أولُ ما يُقرعُ المسامعَ',
  '«كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ»، وتحنيكُ المنذرِ وتسميتُه، و«فليلقنوا لا إله إلا الله» عند النطق.',
  '<h2>من القرآن الكريم</h2>
<p>{فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًۭا ۚ فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا ۚ لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ} <strong>(سورة الروم ٣٠، الآية ٣٠)</strong></p>
<p>{ٱدْعُوهُمْ لِءَابَآئِهِمْ هُوَ أَقْسَطُ عِندَ ٱللَّهِ ۚ فَإِن لَّمْ تَعْلَمُوٓا۟ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَمَوَٰلِيكُمْ ۚ وَلَيْسَ عَلَيْكُمْ جُنَاحٌۭ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ ۚ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًا} <strong>(سورة الأحزاب ٣٣، الآية ٥)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ، فَأَبَوَاهُ يُهَوِّدَانِهِ أَوْ يُنَصِّرَانِهِ أَوْ يُمَجِّسَانِهِ، كَمَثَلِ الْبَهِيمَةِ تُنْتَجُ الْبَهِيمَةَ، هَلْ تَرَى فِيهَا جَدْعَاءَ» — <strong>صحيح البخاري</strong>، برقم ١٣٨٥.</p>
<p>«أُتِيَ بِالْمُنْذِرِ بْنِ أَبِي أُسَيْدٍ إِلَى النَّبِيِّ صلى الله عليه وسلم حِينَ وُلِدَ، فَوَضَعَهُ عَلَى فَخِذِهِ وَأَبُو أُسَيْدٍ جَالِسٌ، فَلَهَا النَّبِيُّ صلى الله عليه وسلم بِشَىْءٍ بَيْنَ يَدَيْهِ، فَأَمَرَ أَبُو أُسَيْدٍ بِابْنِهِ فَاحْتُمِلَ مِنْ فَخِذِ النَّبِيِّ صلى الله عليه وسلم فَاسْتَفَاقَ النَّبِيُّ صلى الله عليه وسلم فَقَالَ أَيْنَ الصَّبِيُّ. فَقَالَ أَبُو أُسَيْدٍ قَلَبْنَاهُ يَا رَسُولَ اللَّهِ. قَالَ مَا اسْمُهُ. قَالَ فُلاَنٌ. قَالَ وَلَكِنْ أَسْمِهِ الْمُنْذِرَ. فَسَمَّاهُ يَوْمَئِذٍ الْمُنْذِرَ» — <strong>صحيح البخاري</strong>، برقم ٦١٩١، كتاب الأدب.</p>
<p>«وُلِدَ لِي غُلاَمٌ فَأَتَيْتُ بِهِ النَّبِيَّ صلى الله عليه وسلم فَسَمَّاهُ إِبْرَاهِيمَ وَحَنَّكَهُ بِتَمْرَةٍ» — <strong>صحيح مسلم</strong>، برقم ٥٦١٥.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«فإذا كان وقت نطقهم فليلقنوا لا إله إلا الله محمد رسول الله وليكن أول ما يقرع مسامعهم معرفة الله سبحانه وتوحيده وأنه سبحانه فوق عرشه ينظر إليهم ويسمع كلامهم وهو معهم أينما كانوا وكان بنو إسرائيل»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب السادس عشر — أول ما يُقرع مسامعهم.</blockquote>
<blockquote>«تسموا بأسماء الأنبياء وأحب الأسماء إلى الله عبد الله وعبد الرحمن وأصدقها حارث وهمام وأقبحها حرب ومرة»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب السادس عشر — أحسنُ الأسماء.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>اخترْ اسمًا يُحبه صاحبه في الناس وفي الملائكة؛ فالاسمُ دعاءٌ كلَّ يوم.</li><li>أولُ ما يُثبَّتُ في أذنه معنى التوحيدِ لا زحمةُ الأسماء.</li><li>إذا بلَغَ فلينسَبْ إلى أبيه؛ فالتسميةُ نسبةٌ لا زينةٌ فقط.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: الروم ٣٠/٣٠؛ الأحزاب ٣٣/٥ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح البخاري ١٣٨٥؛ صحيح البخاري ٦١٩١؛ صحيح مسلم ٥٦١٥ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
