  'tarbiyah-waqt',
  'الثالثة عشرة: الوقتُ والعمرُ: نعمتانِ مغبونٌ فيهما',
  '«نِعْمَتَانِ مَغْبُونٌ فِيهِمَا…» مع وصيةِ الغزالي بلقمانِ ابنه، وكلامِ ابن القيّم في الكسلِ وراحةِ الجسم.',
  '<h2>من القرآن الكريم</h2>
<p>{يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌۭ مَّا قَدَّمَتْ لِغَدٍۢ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ} <strong>(سورة الحشر ٥٩، الآية ١٨)</strong></p>
<p>{بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلْعَصْرِ} <strong>(سورة العصر ١٠٣، الآية ١)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ، الصِّحَّةُ وَالْفَرَاغ» — <strong>صحيح البخاري</strong>، برقم ٦٤١٢، كتاب الرقاق.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«لايكونن الديك أكيس منك، ينادى بالأسحار وأنت نائم»<br>— أبو حامد الغزالي (ت ٥٠٥هـ)، <a href="https://ar.wikisource.org/wiki/%D8%A3%D9%8A%D9%87%D8%A7_%D8%A7%D9%84%D9%88%D9%84%D8%AF">أيها الولد</a>: وصية الغزالي — حكاية لقمان لابنه.</blockquote>
<blockquote>«ويجنبه الكسل والبطالة والدعة والراحة بل يأخذه بأضدادها ولا يريحه إلا بما يجم نفسه وبدنه للشغل فإن الكسل والبطالة عواقب سوء ومغبة ندم وللجد والتعب عواقب حميدة إما في الدنيا وإما في العقبى وإما فيهما فأروح الناس أتعب الناس وأتعب الناس أروح الناس فالسيادة في الدنيا والسعادة في العقبى لا يوصل إليها إلا على جسر من التعب قال يحيى بن أبي كثير لا ينال العلم براحة الجسم»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب السادس عشر — تجنّب الكسل والبطالة.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>الفراغُ والصحةُ مادتا التعليم؛ لا تؤجلهما إلى المرض والانشغال.</li><li>ساعةُ الصبحِ للصغيرِ كساعةِ المكتبِ للكبير: ثبّتْها ولا تساومْ عليها.</li><li>الراحةُ جائزةٌ، البطالةُ لا: «أروحُ الناس أتعبُ الناس».</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: الحشر ٥٩/١٨؛ العصر ١٠٣/١ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح البخاري ٦٤١٢ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: أيها الولد؛ تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D8%A3%D9%8A%D9%87%D8%A7_%D8%A7%D9%84%D9%88%D9%84%D8%AF',
  'أيها الولد — أبو حامد الغزالي (ت ٥٠٥هـ)',
  'https://ar.wikisource.org/wiki/%D8%A3%D9%8A%D9%87%D8%A7_%D8%A7%D9%84%D9%88%D9%84%D8%AF',
  '["الوقت والعمر","تربية الأبناء","أبو حامد الغزالي"]'::jsonb,
  '{"البطاقة":"١٣ من ١٥","من القرآن":"الحشر ٥٩/١٨؛ العصر ١٠٣/١","من الحديث":"صحيح البخاري ٦٤١٢","من الكتب":"أيها الولد؛ تحفة المودود بأحكام المولود","الرخصة":"ويكي مصدر — CC BY-SA 4.0؛ AlQuran Cloud (Tanzil)؛ hadith-api — Unlicense"}'::jsonb,
  'published', 30,
  '2026-10-22T00:00:00.000Z'::timestamptz
where not exists (select 1 from public.items where section_id = 'tarbiyah' and slug = 'tarbiyah-waqt');

-- ١٤) الرابعة عشرة: مَيلُ الصبيِّ: انظرْ إلى ما أُعطيَ لا إلى ما تريد
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-mayl',
  'الرابعة عشرة: مَيلُ الصبيِّ: انظرْ إلى ما أُعطيَ لا إلى ما تريد',
  '«إِنَّ فِيكَ لَخَصْلَتَيْنِ…» — نظرُ النبيِّ ﷺ إلى معدنِ الأشجِّ، وكلامُ ابن القيّم في حملِ الصبيِّ على ما استعدَّ له.',
  '<h2>من القرآن الكريم</h2>
<p>{قُلْ كُلٌّۭ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًۭا} <strong>(سورة الإسراء ١٧، الآية ٨٤)</strong></p>
<p>{يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ ۚ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًۭا كَثِيرًۭا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ} <strong>(سورة البقرة ٢، الآية ٢٦٩)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«لأَشَجِّ عَبْدِ الْقَيْسِ إِنَّ فِيكَ لَخَصْلَتَيْنِ يُحِبُّهُمَا اللَّهُ الْحِلْمُ وَالأَنَاة» — <strong>صحيح مسلم</strong>، برقم ١١٨، كتاب الإيمان.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«ومما ينبغي أن يعتمد حال الصبي وما هو مستعد له من الأعمال ومهيأ له منها فيعلم أنه مخلوق له فلا يحمله على غيره ما كان مأذونا فيه شرعا فإنه إن حمله على غير ما هو مستعد له لم يفلح فيه وفاته ما هو مهيأ له»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب السادس عشر — اعتماد حال الصبي ومهيّأ له.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>اختبرْ ميلَه بالتمرينِ لا بالسؤال؛ الفهمُ صحيحُ الإدراكِ يُرى في الصنعة.</li><li>لا تُحمّله ما لا يُطاقُ منه: «إن حمله على غير ما استعد له لم يفلح».</li><li>خصلةٌ واحدةٌ محمودةٌ تُرى في الصبيِّ تُبنى، لا تُنتقد لأنها ليست فيك.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: الإسراء ١٧/٨٤؛ البقرة ٢/٢٦٩ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح مسلم ١١٨ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  'تحفة المودود بأحكام المولود — ابن القيّم (ت ٧٥١هـ)',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
