-- ١٥) الخامسة عشرة: الدعاءُ: قرةُ العينِ لا الزينةُ فقط
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'tarbiyah',
  'tarbiyah-dua',
  'الخامسة عشرة: الدعاءُ: قرةُ العينِ لا الزينةُ فقط',
  '«رَبَّنَا هَبْ لَنَا… قُرَّةَ أَعْيُنٍ»، ودعوةُ أخيك بظهرِ الغيبِ، ودعوةُ أنسٍ: «اللهم أكثر ماله وولده».',
  '<h2>من القرآن الكريم</h2>
<p>{وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍۢ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا} <strong>(سورة الفرقان ٢٥، الآية ٧٤)</strong></p>
<p>{رَبِّ هَبْ لِى مِنَ ٱلصَّٰلِحِينَ} <strong>(سورة الصافات ٣٧، الآية ١٠٠)</strong></p>
<p>{رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى ۚ رَبَّنَا وَتَقَبَّلْ دُعَآءِ} <strong>(سورة إبراهيم ١٤، الآية ٤٠)</strong></p>
<h2>من سنة النبي ﷺ</h2>
<p>«مَا مِنْ عَبْدٍ مُسْلِمٍ يَدْعُو لأَخِيهِ بِظَهْرِ الْغَيْبِ إِلاَّ قَالَ الْمَلَكُ وَلَكَ بِمِثْلٍ» — <strong>صحيح مسلم</strong>، برقم ٦٩٢٧، كتاب الذكر والدعاء والتوبة والاستغفار.</p>
<p>«اللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ، وَبَارِكْ لَهُ فِيمَا أَعْطَيْتَهُ» — <strong>صحيح البخاري</strong>، برقم ٦٣٣٤، كتاب الدعوات.</p>
<h2>من كلام أهل العلم بالتربية</h2>
<blockquote>«فقال يا أبا سعيد ما هذه القرة الأعين أفي الدنيا أم في الآخرة قال لا بل والله في الدنيا قال وما هي قال والله أن يري الله العبد من زوجته من أخيه من حميمه طاعة الله لا والله ما شيء أحب إلى المرء المسلم من أن يرى ولدا أو والدا أو حميما أو أخا مطيعا لله تعالى»<br>— ابن القيّم (ت ٧٥١هـ)، <a href="https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF">تحفة المودود بأحكام المولود</a>: الباب الخامس عشر — قول الحسن في قرة الأعين.</blockquote>
<blockquote>«وأما الدعاء الذى سألت منى فاطلبه من دعوات الصحاح، واقرا هذا الدعاء فى أوقاتك، خصوصا فى أعقاب صلواتك: اللهم إنى أسألك من النعمة تمامها، ومن العصمة دوامها، ومن الرحمة شمولها، ومن العافية حصولها، ومن العيش أرغده، ومن العمر أسعده ومن الاحسان أتمه، ومن الانعام أعمه، ومن الفضل أعذبه، ومن اللطف أقربه»<br>— أبو حامد الغزالي (ت ٥٠٥هـ)، <a href="https://ar.wikisource.org/wiki/%D8%A3%D9%8A%D9%87%D8%A7_%D8%A7%D9%84%D9%88%D9%84%D8%AF">أيها الولد</a>: دعوة الغزالي في ختام الرسالة.</blockquote>
<h2>خلاصةُ البطاقة</h2>
<ul><li>ادعُ له بظهرِ الغيبِ في السجدةِ الأخيرة؛ فهي أسرعُ ما يُرجى لنفسك بغيرك.</li><li>لا تجعلِ الدعاءَ بديلًا عن التعهد، ولا التعهدَ بديلًا عن الدعاء.</li><li>اسألْ له الطاعةَ لا الذُّكرَ؛ فقرةُ العينِ ما في الحديثِ لا ما في الناس.</li></ul>
<p><em>أسطرُ «خلاصةُ البطاقة» تحريرٌ من التطبيق لجمعِ ما في البطاقة، لا روايةٌ ولا فتوى؛ والمنقولُ فيها باسمِ قائله أعلاه.</em></p>
<h2>المصادرُ في هذه البطاقة</h2>
<p>الآياتُ: الفرقان ٢٥/٧٤؛ الصافات ٣٧/١٠٠؛ إبراهيم ١٤/٤٠ — بالرسم العثماني (نصُّ Tanzil) من AlQuran Cloud. الأحاديث: صحيح مسلم ٦٩٢٧؛ صحيح البخاري ٦٣٣٤ — من نسخة التطبيق نفسِها (ترقيمُ محمد فؤاد عبد الباقي، ومصدرُها fawazahmed0/hadith-api برخصة Unlicense). منقولاتُ التربية: تحفة المودود بأحكام المولود؛ أيها الولد — من ar.wikisource.org برخصة «رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</p>',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  'تحفة المودود بأحكام المولود — ابن القيّم (ت ٧٥١هـ)',
  'https://ar.wikisource.org/wiki/%D9%83%D8%AA%D8%A7%D8%A8_%D8%AA%D8%AD%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AF%D9%88%D8%AF',
  '["الدعاء","تربية الأبناء","ابن القيّم"]'::jsonb,
  '{"البطاقة":"١٥ من ١٥","من القرآن":"الفرقان ٢٥/٧٤؛ الصافات ٣٧/١٠٠؛ إبراهيم ١٤/٤٠","من الحديث":"صحيح مسلم ٦٩٢٧؛ صحيح البخاري ٦٣٣٤","من الكتب":"تحفة المودود بأحكام المولود؛ أيها الولد","الرخصة":"ويكي مصدر — CC BY-SA 4.0؛ AlQuran Cloud (Tanzil)؛ hadith-api — Unlicense"}'::jsonb,
  'published', 10,
  '2026-10-22T00:00:00.000Z'::timestamptz
