-- تدقيقٌ بعد التنفيذ: خمسَ عشرةَ بطاقةً؟ وكلُّ واحدةٍ فيها آيةٌ وحديثٌ ومنقولٌ ومصدرُه؟
do $$
declare n int; miss int; bad int;
begin
  select count(*) into n from public.items where section_id = 'tarbiyah';
  select count(*) into miss from public.items where section_id = 'tarbiyah'
    and (fields->>'من القرآن' is null or fields->>'من الحديث' is null
         or fields->>'من الكتب' is null or source_url is null or link is null or length(body) < 800);
  select count(*) into bad from public.items where section_id = 'tarbiyah'
    and (length(link) > 500 or length(source_url) > 500
         or link ~ '%([0-9a-fA-F]?)$' or length(title) > 200 or length(subtitle) > 240);
  if n <> 15 then raise warning 'WARNING: البطاقاتُ المنشورةُ % بدلًا من % — أكملْ بذرةَ الناقصِ منها.', n, 15; end if;
  if miss > 0 then raise warning 'WARNING: % بطاقةً في قسمِ التربيةِ بلا مصدرٍ كامل — راجعِ الحقولَ والخريطةَ.', miss; end if;
  if bad > 0 then raise warning 'WARNING: % بطاقةً برابطةٍ أو عنوانٍ يخالفُ سقفَ الناشر — لا تُنشرُ كاملةً.', bad; end if;
end $$;

select i.slug, i.title, i.sort_order,
  length(i.body) as body_chars,
  coalesce(i.fields->>'البطاقة','—') as no,
  coalesce(i.fields->>'من الحديث','—') as hadith,
  coalesce(i.source_name,'—') as source
from public.items i where i.section_id = 'tarbiyah' order by i.sort_order desc;
